UPDATE artwork_translations t SET summary=CASE WHEN t.locale='zh-CN' THEN CASE WHEN at.name IS NULL THEN '《'||t.title||'》以'||aw.medium||'保存匿名或集体创作的关键视觉传统。' ELSE '《'||t.title||'》由'||at.name||'以'||aw.medium||'创作，'||CASE WHEN aw.medium ~* 'architecture|cathedral|portal|colonnade|urban design' THEN '以结构、光线和行走路线组织空间。' WHEN aw.medium ~* 'sculpture|bronze|marble|relief|tympanum' THEN '以体量、姿态和环绕观看建立形象。' WHEN aw.medium ~* 'manuscript|etching|woodcut|lithograph|print|poster|embroidery' THEN '以线条、层次和可传播媒介组织图像。' WHEN aw.medium ~* 'mosaic|fresco' THEN '把图像、色彩和建筑表面结合。' WHEN aw.medium ~* 'readymade|wheel|urinal|tape|collage' THEN '重新界定材料、制作与艺术制度。' ELSE '以构图、色彩、光线和空间关系组织观看。' END END ELSE CASE WHEN at.name IS NULL THEN t.title||' preserves a major anonymous or collective visual tradition in '||aw.medium||'.' ELSE t.title||', made by '||at.name||' in '||aw.medium||', organises a key problem of form, image and viewing.' END END,description=CASE WHEN t.locale='zh-CN' THEN '《'||t.title||'》创作于'||CASE WHEN aw.creation_start_year=aw.creation_end_year THEN CASE WHEN aw.creation_start_year<0 THEN '约公元前 '||abs(aw.creation_start_year)||' 年' ELSE aw.creation_start_year||' 年' END ELSE CASE WHEN aw.creation_start_year<0 AND aw.creation_end_year<0 THEN '约公元前 '||abs(aw.creation_start_year)||'–'||abs(aw.creation_end_year)||' 年' ELSE aw.creation_start_year||'–'||aw.creation_end_year||' 年' END END||'，媒介为'||aw.medium||'。'||CASE WHEN aw.medium ~* 'architecture|cathedral|portal|colonnade|urban design' THEN '作品把结构、光线、表面装饰与人的行走路线组织为整体空间。' WHEN aw.medium ~* 'sculpture|bronze|marble|relief|tympanum' THEN '作品通过体量、姿态、表面和环绕观看建立形象。' WHEN aw.medium ~* 'manuscript|etching|woodcut|lithograph|print|poster|embroidery' THEN '作品利用线条、层次与可传播的图像媒介组织叙事。' WHEN aw.medium ~* 'mosaic|fresco' THEN '作品把图像、色彩与建筑表面结合，使观看与场所不可分离。' WHEN aw.medium ~* 'readymade|wheel|urinal|tape|collage' THEN '作品重新界定日常材料、制作行为与艺术制度之间的关系。' ELSE '作品通过构图、色彩、光线和人物或空间关系组织观看。' END||CASE ch.slug WHEN 'classical-antiquity' THEN '它显示古典艺术如何以比例、身体和公共纪念塑造后世的视觉标准。' WHEN 'medieval' THEN '它连接礼仪、城市工坊、建筑空间和中世纪图像传播。' WHEN 'renaissance' THEN '它体现文艺复兴对古典传统、自然观察、透视和个人创作身份的重组。' WHEN 'baroque' THEN '它体现巴洛克或洛可可对戏剧、感官、宫廷与宗教空间的调动。' WHEN 'neoclassicism-and-romanticism' THEN '它把学院规范、革命历史、个人情感和崇高自然置于新的公共观看中。' WHEN 'modernism' THEN '它把现代生活、社会现实和变化中的光色经验带入艺术主叙事。' WHEN 'modernism-early' THEN '它推动结构、象征、表现性形象与世纪末文化之间的新关系。' ELSE '它回应工业化、战争与先锋运动对艺术材料、形式和观念的重构。' END ELSE t.title||' was made in '||CASE WHEN aw.creation_start_year=aw.creation_end_year THEN CASE WHEN aw.creation_start_year<0 THEN 'c. '||abs(aw.creation_start_year)||' BCE' ELSE aw.creation_start_year::text END ELSE CASE WHEN aw.creation_start_year<0 AND aw.creation_end_year<0 THEN 'c. '||abs(aw.creation_start_year)||'–'||abs(aw.creation_end_year)||' BCE' ELSE aw.creation_start_year||'–'||aw.creation_end_year END END||' in '||aw.medium||'. '||CASE WHEN aw.medium ~* 'architecture|cathedral|portal|colonnade|urban design' THEN 'It organises structure, light, surface and bodily movement as a single spatial experience. ' WHEN aw.medium ~* 'sculpture|bronze|marble|relief|tympanum' THEN 'It builds meaning through volume, pose, surface and viewing in the round. ' WHEN aw.medium ~* 'manuscript|etching|woodcut|lithograph|print|poster|embroidery' THEN 'It uses line, layering and a reproducible or portable image medium to organise narrative. ' WHEN aw.medium ~* 'mosaic|fresco' THEN 'It binds image and colour to an architectural surface, making viewing inseparable from place. ' WHEN aw.medium ~* 'readymade|wheel|urinal|tape|collage' THEN 'It redefines the relation between ordinary material, artistic making and the institution of art. ' ELSE 'It organises viewing through composition, colour, light and the relation of figures or space. ' END||CASE ch.slug WHEN 'classical-antiquity' THEN 'It shows how classical art made proportion, the body and public monument into enduring visual standards.' WHEN 'medieval' THEN 'It connects ritual, urban workshops, architectural space and medieval image circulation.' WHEN 'renaissance' THEN 'It reflects the Renaissance reworking of antiquity, natural observation, perspective and artistic identity.' WHEN 'baroque' THEN 'It mobilises Baroque or Rococo drama, sensation, court culture and religious space.' WHEN 'neoclassicism-and-romanticism' THEN 'It places academic order, revolutionary history, personal feeling and sublime nature before a new public.' WHEN 'modernism' THEN 'It brings modern life, social reality and changing experiences of light and colour into the main narrative of art.' WHEN 'modernism-early' THEN 'It advances new relations among structure, symbolism, expressive imagery and fin-de-siècle culture.' ELSE 'It answers industrialisation, war and the avant-garde reconstruction of artistic material, form and concept.' END END FROM artworks aw LEFT JOIN artists a ON a.id=aw.primary_artist_id LEFT JOIN artist_translations at ON at.artist_id=a.id JOIN chapters ch ON ch.id=aw.chapter_id WHERE t.artwork_id=aw.id AND aw.work_id='10000000-0000-4000-8000-000000000009' AND (at.locale=t.locale OR at.artist_id IS NULL);



COMMIT;
