INSERT INTO artist_translations(artist_id,locale,name,summary,modern_status,period_titles,status,full_name,aliases,formal_titles) SELECT id,'zh-CN','胡安·米罗','胡安·米罗以作品、媒介和城市网络进入欧洲艺术史主干。','早期现代主义与战争核心人物',ARRAY['surrealism']::text[],'published','胡安·米罗','{}','{}' FROM artists WHERE work_id='10000000-0000-4000-8000-000000000009' AND slug='joan-miro' ON CONFLICT(artist_id,locale) DO UPDATE SET name=EXCLUDED.name,summary=EXCLUDED.summary,modern_status=EXCLUDED.modern_status,period_titles=EXCLUDED.period_titles,status=EXCLUDED.status,full_name=EXCLUDED.full_name;
INSERT INTO artist_translations(artist_id,locale,name,summary,modern_status,period_titles,status,full_name,aliases,formal_titles) SELECT id,'en','Joan Miró','Joan Miró enters the main narrative of European art history through works, media and city networks.','Core figure in Early Modernism and War',ARRAY['surrealism']::text[],'published','Joan Miró i Ferrà','{}','{}' FROM artists WHERE work_id='10000000-0000-4000-8000-000000000009' AND slug='joan-miro' ON CONFLICT(artist_id,locale) DO UPDATE SET name=EXCLUDED.name,summary=EXCLUDED.summary,modern_status=EXCLUDED.modern_status,period_titles=EXCLUDED.period_titles,status=EXCLUDED.status,full_name=EXCLUDED.full_name;
