INSERT INTO character_translations(character_id,locale,name,summary,aliases,detail,motivation,status) SELECT a.character_id,t.locale,COALESCE(NULLIF(t.full_name,''),t.name),t.summary,t.aliases,CASE WHEN t.locale='zh-CN' THEN '艺术家与人物身份统一；作品、事件、地点、来源和关系沿用同一人物链。' ELSE 'Artist and person identities are unified; works, events, places, sources and relations use the same person chain.' END,CASE WHEN t.locale='zh-CN' THEN concat_ws('；',t.modern_status,array_to_string(t.period_titles,'、')) ELSE concat_ws('; ',t.modern_status,array_to_string(t.period_titles,'; ')) END,t.status FROM artists a JOIN artist_translations t ON t.artist_id=a.id WHERE a.work_id='10000000-0000-4000-8000-000000000009' AND a.character_id IS NOT NULL ON CONFLICT(character_id,locale) DO UPDATE SET name=EXCLUDED.name,summary=EXCLUDED.summary,aliases=EXCLUDED.aliases,detail=EXCLUDED.detail,motivation=EXCLUDED.motivation,status=EXCLUDED.status;
