INSERT INTO event_translations(event_id,locale,title,summary,status,time_label,detail,significance) SELECT id,'zh-CN','战后欧洲藏品清点与追索展开','战争结束后，盟军、政府与博物馆开始清点、归还和追索被掠夺或转移的文化财产。','published','1945–1951 年','战争结束后，盟军、政府与博物馆开始清点、归还和追索被掠夺或转移的文化财产。','该过程把来源研究、返还和馆藏责任带入现代博物馆制度。' FROM events WHERE work_id='10000000-0000-4000-8000-000000000009' AND slug='postwar-restitution-programs' ON CONFLICT(event_id,locale) DO UPDATE SET title=EXCLUDED.title,summary=EXCLUDED.summary,status=EXCLUDED.status,time_label=EXCLUDED.time_label,detail=EXCLUDED.detail,significance=EXCLUDED.significance;
